BEGIN;
CREATE TEMP TABLE snapshot_evidence(label text,data jsonb);
DO $t$ DECLARE a uuid:='99b67080-a6eb-4feb-bd8e-92a287b430aa'; p uuid:='e4f51cd6-fb25-475e-980a-5e46070d678f'; c uuid:='152291ba-f894-401f-85fe-f68ba29af7d0'; b uuid; i uuid; mi uuid; fi uuid:=gen_random_uuid(); m uuid; r uuid:=gen_random_uuid(); f uuid:=gen_random_uuid(); d date; v jsonb;
BEGIN
PERFORM set_config('request.jwt.claim.sub',a::text,true);
SET LOCAL ROLE authenticated; v:=public.get_running_bill(p,'2026-11-22'); RESET ROLE;
IF (v->'totals'->>'value_earned')::numeric<>151000 OR (v->'totals'->>'own_labour_cost')::numeric<>6365.46 OR (v->'totals'->>'subcontract_accrued')::numeric<>0 OR (v->'totals'->>'excess_value')::numeric<>19500 THEN RAISE EXCEPTION 'Baseline mismatch'; END IF;
INSERT INTO snapshot_evidence VALUES('Running Bill',v->'totals');
SELECT id INTO b FROM public.project_boq WHERE project_id=p ORDER BY version_number DESC,uploaded_at DESC,id DESC LIMIT 1;
SELECT id INTO i FROM public.project_boq_items WHERE boq_id=b ORDER BY sno LIMIT 1;
SELECT id INTO mi FROM public.project_boq_items WHERE boq_id=b AND id<>i ORDER BY sno LIMIT 1;
SELECT id INTO m FROM public.modules WHERE project_id=p AND NOT is_archived LIMIT 1;
SELECT day::date INTO d FROM generate_series(current_date-2,current_date,interval '1 day') day WHERE NOT EXISTS(SELECT 1 FROM public.factory_daily_reports WHERE report_date=day::date) AND NOT EXISTS(SELECT 1 FROM public.labour_attendance WHERE project_id=p AND work_date=day::date AND hours>0 AND NOT hours_confirmed) ORDER BY day LIMIT 1;
IF d IS NULL THEN RAISE EXCEPTION 'No free fixture date'; END IF;
UPDATE public.daily_measurements SET is_archived=true WHERE project_id=p AND measurement_date=d AND trade='daily_site_report';
INSERT INTO public.project_boq_items(id,boq_id,sno,item_description,unit,boq_qty,boq_rate,work_location) VALUES(fi,b,990001,'Snapshot factory fixture','kg',100,0,'factory');
SET LOCAL ROLE authenticated; PERFORM public.set_material_rate(p,i,125); PERFORM public.set_material_rate(p,fi,40); PERFORM public.upsert_subcontract_rate(p,i,c,'per_unit',12,NULL,NULL,true,true); RESET ROLE;
INSERT INTO public.daily_measurements(id,project_id,measurement_date,location,trade,report_status,notes,submitted_by,created_by,updated_by) VALUES(r,p,d,'site','daily_site_report','draft','Snapshot fixture',a,a,a);
INSERT INTO public.site_report_quantities(report_id,project_id,boq_item_id,today_qty,contractor_id,created_by,updated_by) VALUES(r,p,i,2,NULL,a,a),(r,p,i,5,c,a,a),(r,p,mi,4,NULL,a,a);
INSERT INTO public.factory_daily_reports(id,report_date,status,notes,created_by,updated_by) VALUES(f,d,'draft','Snapshot factory fixture',a,a);
INSERT INTO public.factory_report_blocks(report_id,module_id,stage,stage_status,progress_pct,created_by,updated_by) VALUES(f,m,'Main Frame','ongoing',10,a,a);
INSERT INTO public.factory_report_quantities(report_id,module_id,stage,boq_item_id,today_qty,unit,created_by,updated_by) VALUES(f,m,'Main Frame',fi,3,'kg',a,a);
SET LOCAL ROLE authenticated; PERFORM public.submit_site_report(r); PERFORM public.submit_factory_report(f); RESET ROLE;
IF NOT EXISTS(SELECT 1 FROM public.site_report_quantities WHERE report_id=r AND boq_item_id=i AND contractor_id IS NULL AND material_rate_used=125 AND material_amount_inr=250 AND material_rate_missing=false) THEN RAISE EXCEPTION 'Own material mismatch'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.site_report_quantities WHERE report_id=r AND contractor_id=c AND material_rate_used=125 AND material_amount_inr=0 AND material_rate_missing=false) THEN RAISE EXCEPTION 'Included material mismatch'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.site_report_quantities WHERE report_id=r AND boq_item_id=mi AND material_rate_used IS NULL AND material_amount_inr=0 AND material_rate_missing=true) THEN RAISE EXCEPTION 'Missing material mismatch'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.factory_report_quantities WHERE report_id=f AND material_rate_used=40 AND material_amount_inr=120 AND material_rate_missing=false) THEN RAISE EXCEPTION 'Factory material mismatch'; END IF;
INSERT INTO snapshot_evidence SELECT 'Site',jsonb_build_object('qty',today_qty,'material_rate_used',material_rate_used,'material_amount_inr',material_amount_inr,'material_rate_missing',material_rate_missing,'includes_material',contractor_id IS NOT NULL) FROM public.site_report_quantities WHERE report_id=r;
INSERT INTO snapshot_evidence SELECT 'Factory',jsonb_build_object('qty',today_qty,'material_rate_used',material_rate_used,'material_amount_inr',material_amount_inr,'material_rate_missing',material_rate_missing) FROM public.factory_report_quantities WHERE report_id=f;
SET LOCAL ROLE authenticated; PERFORM public.set_material_rate(p,i,999); PERFORM public.set_material_rate(p,fi,888);
PERFORM public.save_site_report_draft(p,d,jsonb_build_object('quantities',jsonb_build_array(jsonb_build_object('boq_item_id',i,'today_qty',9),jsonb_build_object('boq_item_id',i,'contractor_id',c,'today_qty',5),jsonb_build_object('boq_item_id',mi,'today_qty',4)))); PERFORM public.submit_site_report(r);
PERFORM public.save_factory_report_draft(d,jsonb_build_object('quantities',jsonb_build_array(jsonb_build_object('module_id',m,'stage','Main Frame','boq_item_id',fi,'today_qty',9)))); RESET ROLE;
IF NOT EXISTS(SELECT 1 FROM public.site_report_quantities WHERE report_id=r AND contractor_id IS NULL AND boq_item_id=i AND today_qty=9 AND material_rate_used=125 AND material_amount_inr=250) OR NOT EXISTS(SELECT 1 FROM public.factory_report_quantities WHERE report_id=f AND today_qty=9 AND material_rate_used=40 AND material_amount_inr=120) THEN RAISE EXCEPTION 'Resubmit rewrote snapshots'; END IF;
END $t$;
SELECT jsonb_agg(to_jsonb(e)) evidence FROM snapshot_evidence e;
ROLLBACK;
